export function getDemoDictionary(locale: Locale) {
  const index = localeIndexes[locale]

  if (index === 0) return {}

  return Object.fromEntries(phrases.map((row) => [row[0], row[index]]))
}

export function translateDemoText(locale: Locale, value: string) {
  const dictionary = getDemoDictionary(locale)
  const replacements = Object.entries(dictionary).sort((a, b) => b[0].length - a[0].length)

  return replacements.reduce((text, [source, target]) => {
    if (!exactOnlySources.has(source)) {
      return text.split(source).join(target)
    }

    const start = text.search(/\S/)
    if (start === -1) return text

    const end = text.search(/\s*$/)
    if (text.slice(start, end) !== source) return text

    return `${text.slice(0, start)}${target}${text.slice(end)}`
  }, value)
}
